  const zhToEn=new Map(staticPairs),enToZh=new Map(staticPairs.map(pair=>[pair[1],pair[0]]));
  const translateExact=value=>{const raw=String(value??''),trimmed=raw.trim(),dictionary=locale().startsWith('zh')?enToZh:zhToEn,translated=dictionary.get(trimmed);return translated===undefined?raw:raw.replace(trimmed,translated)};
  const localizeStatic=()=>{document.title=text('用量管理','Usage management');const root=document.querySelector('.cc-panel');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:node=>node.parentElement?.closest('script,style,svg')?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT});for(let node=walker.nextNode();node;node=walker.nextNode())node.nodeValue=translateExact(node.nodeValue);root.querySelectorAll('[placeholder],[aria-label],[title]').forEach(node=>{for(const attribute of ['placeholder','aria-label','title'])if(node.hasAttribute(attribute))node.setAttribute(attribute,translateExact(node.getAttribute(attribute)))})};
  const toast=(message,ok=true)=>{if(!message)return;let region=document.getElementById('toast-region');if(!region){region=document.createElement('div');region.id='toast-region';region.setAttribute('aria-live','assertive');document.body.append(region)}const item=document.createElement('div');item.setAttribute('role',ok?'status':'alert');item.textContent=message;region.append(item);item.onclick=()=>item.remove();setTimeout(()=>item.remove(),ok?3600:6500)};
