  const nativeFetch=window.fetch?.bind(window);if(nativeFetch&&!window.__ccFetchTimeoutInstalled){window.__ccFetchTimeoutInstalled=true;window.fetch=async(input,init={})=>{if(typeof AbortController==='undefined')return nativeFetch(input,init);const options=init||{},url=typeof input==='string'?input:input?.url||'',controller=new AbortController(),callerSignal=Object.prototype.hasOwnProperty.call(options,'signal')?options.signal:(typeof Request!=='undefined'&&input instanceof Request?input.signal:undefined);let timedOut=false;if(callerSignal){if(callerSignal.aborted)controller.abort(callerSignal.reason);else callerSignal.addEventListener('abort',()=>controller.abort(callerSignal.reason),{once:true})}const timer=setTimeout(()=>{timedOut=true;controller.abort()},15000);try{return await nativeFetch(input,{...options,signal:controller.signal})}catch(error){if(timedOut&&!callerSignal?.aborted)throw new Error(text('管理请求超时，请检查 CPA 连接后重试。','The management request timed out. Check the CPA connection and retry.'));throw error}finally{clearTimeout(timer)}}}
